/* NEBSOFT Kargo & Kurye — gönderi kabul, etiket, zimmet/dağıtım, kurye teslim ekranı, COD mutabakatı, cari ve raporlar */
(function () {
  'use strict';
  const { esc, $, $$, on, icon, money, num, toast, modal, confirm, formModal, table, chart, badge, kpi, pageHead, sum, addDays, iso, today } = NS;
  const K = window.KARGO;
  const db = new NS.DB('kargo', K.seed);
  const S = () => db.settings({});
  const cour = (id) => db.get('couriers', id) || { name: id === 'partner' ? 'Anlaşmalı kargo' : 'Atanmadı', zone: [] };
  const cari = (id) => db.get('caris', id);
  const r2 = (n) => Math.round(n * 100) / 100;
  const me = () => (NS.currentUser || {}).name || '';
  const isAdm = () => !NS.currentUser || NS.currentUser.role === 'admin';
  const canOffice = () => !NS.currentUser || ['admin', 'kabul'].includes(NS.currentUser.role); // kurye başka gönderi üzerinde işlem yapmaz
  // Gönderi numarası: aynı milisaniyede (toplu aktarım) çakışmasın diye sayaçla
  let noSeq = 0; const newNo = () => { let n; do { n = 'HK' + (Date.now() + noSeq++).toString().slice(-9); } while (db.find('ships', (s) => s.no === n)); return n; };
  const stB = (s) => badge(K.ST[s][0], K.ST[s][1]);
  // Alıcının takip sayfasından bildirdiği teslimat tercihi (kurye ekranında öne çıkar)
  const PREF = { komsu: 'Komşuya bırak', gorevli: 'Görevliye / kapıcıya bırak', sube: 'Şubeden alacak', gun: 'Başka gün' };
  const prefTxt = (sh) => [sh.pref ? `${PREF[sh.pref.type]}${sh.pref.note ? ': ' + sh.pref.note : ''}${sh.pref.date ? ' · ' + NS.date(sh.pref.date) : ''}` : '', sh.retryDate ? 'Yeniden teslimat: ' + NS.date(sh.retryDate) : ''].filter(Boolean).join(' · ');
  const trackUrl = (sh) => location.href.replace(/index\.html.*$/, '').replace(/#.*$/, '') + 'takip.html?no=' + sh.no;
  const myCourier = () => (NS.currentUser && NS.currentUser.role === 'kurye' ? NS.currentUser.courier : null);
  function setStatus(sh, status, note) { sh.status = status; sh.history.push({ at: new Date().toISOString(), status, note: note || K.ST[status][0], user: (NS.currentUser || {}).name }); }
  const suggest = (sh) => db.all('couriers').find((c) => c.zone.includes(sh.receiver.district)) || null;
  // Gönderi ücreti kim öder: peşin (kabulde alınır), kurumsal cari (ay sonu fatura), alıcı (kurye kapıda alır). Eski kayıtlarda alan yoksa peşin sayılır.
  const PAYER = { pesin: 'Gönderici peşin', cari: 'Kurumsal cari (ay sonu)', alici: 'Alıcı öder (kapıda)' };
  const payerOf = (s) => s.payer || (s.cari ? 'cari' : 'pesin');
  const feeB = (s) => (payerOf(s) === 'cari' ? badge('Cari', 'info') : s.payer === 'alici' ? (s.feeCollected ? badge('Ücret alındı', 'ok') : badge('Ücret alıcıdan', 'warn')) : badge('Peşin' + (s.feePay ? ' · ' + (s.feePay === 'kart' ? 'kart' : 'nakit') : ''), 'ok'));
  const vat = () => Number(S().vat ?? 20);
  const cash = (s) => (s.codCollected || 0) + (s.feeCollected || 0); // kuryenin üzerindeki para: KT + alıcı ödemeli ücret
  // SMS sonucu olduğu gibi yazılır (simülasyon/kapalıysa "gönderildi" denmez)
  const smsTo = async (phone, text) => { const r = NS.integ ? await NS.integ.sms(phone, text, { silent: true }) : { ok: false, error: 'SMS tanımlı değil' }; return r.ok && !r.simulated ? 'alıcıya SMS gönderildi' : r.simulated ? 'SMS TEST (gönderilmedi)' : `SMS gönderilmedi: ${r.error || 'kapalı'}`; };
  // Konum (izin verilirse): teslim / teslim edilemedi anının kanıtı
  const here = () => new Promise((res) => { if (!navigator.geolocation) return res(null); navigator.geolocation.getCurrentPosition((p) => res({ lat: Math.round(p.coords.latitude * 1e5) / 1e5, lng: Math.round(p.coords.longitude * 1e5) / 1e5, acc: Math.round(p.coords.accuracy), at: new Date().toISOString() }), () => res(null), { timeout: 8000, maximumAge: 60000, enableHighAccuracy: true }); });
  // Fotoğraf küçültülür (en çok 480 px, JPEG): tarayıcı deposu dolmasın
  const shrink = (file) => new Promise((res) => { if (!file) return res(''); const fr = new FileReader(); fr.onload = () => { const im = new Image(); im.onload = () => { const k = Math.min(1, 480 / Math.max(im.width, im.height)); const c = document.createElement('canvas'); c.width = Math.round(im.width * k); c.height = Math.round(im.height * k); c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); res(c.toDataURL('image/jpeg', 0.55)); }; im.onerror = () => res(''); im.src = fr.result; }; fr.readAsDataURL(file); });
  const mapA = (p) => (p ? `<a href="https://www.google.com/maps?q=${p.lat},${p.lng}" target="_blank" rel="noopener">${p.lat}, ${p.lng}</a> <span class="faint">(±${p.acc} m)</span>` : '<span class="faint">konum alınamadı</span>');

  // ---------- Gönderi kabul ----------
  function intakePage(el, p, app) {
    const st = S();
    el.innerHTML = pageHead('Gönderi Kabul', 'Bilgileri girin; fiyat anında hesaplanır, etiket otomatik yazdırılır') + `<div class="grid g-21"><div class="col" style="gap:16px">
      <div class="card pad" id="sf"><h3 class="mb">Gönderici</h3>${NS.fieldsHtml([{ name: 'cari', label: 'Kurumsal müşteri', type: 'select', empty: 'Bireysel gönderici', options: db.all('caris').map((c) => ({ value: c.id, label: `${c.name} (%${c.discount} indirim)` })) }, { name: 'sname', label: 'Ad / firma' }, { name: 'sphone', label: 'Telefon' }, { name: 'sdistrict', label: 'İlçe', type: 'select', options: K.DISTRICTS }])}</div>
      <div class="card pad" id="rf"><h3 class="mb">Alıcı</h3>${NS.fieldsHtml([{ name: 'rname', label: 'Ad soyad', required: true }, { name: 'rphone', label: 'Telefon', required: true, type: 'tel' }, { name: 'region', label: 'Bölge', type: 'select', options: Object.entries(K.REGION).map(([value, v]) => ({ value, label: v[0] })) }, { name: 'rcity', label: 'Şehir', value: 'İstanbul' }, { name: 'rdistrict', label: 'İlçe (şehir içi)', type: 'select', options: K.DISTRICTS }, { name: 'raddress', label: 'Açık adres', required: true, full: true }])}</div>
      <div class="card pad" id="pf"><h3 class="mb">Paket</h3>${NS.fieldsHtml([...(branches().length ? [{ name: 'branch', label: 'Kabul şubesi', type: 'select', options: branches() }] : []), { name: 'service', label: 'Hizmet', type: 'select', options: Object.entries(K.SERVICE).map(([value, v]) => ({ value, label: v[0] })) }, { name: 'pieces', label: 'Parça adedi', type: 'number', value: 1 }, { name: 'w', label: 'En (cm)', type: 'number', value: 30 }, { name: 'l', label: 'Boy (cm)', type: 'number', value: 20 }, { name: 'h', label: 'Yükseklik (cm)', type: 'number', value: 15 }, { name: 'kg', label: 'Ağırlık (kg)', type: 'number', value: 2, step: '0.1' }, { name: 'cod', label: 'Kapıda tahsilat tutarı (₺)', type: 'number', value: 0, hint: 'Alıcıdan tahsil edilip göndericiye aktarılır' }, { name: 'content', label: 'İçerik', placeholder: 'Giysi, evrak, elektronik...' }, { name: 'payer', label: 'Gönderi ücretini kim öder', type: 'select', options: Object.entries(PAYER).map(([value, label]) => ({ value, label })) }, { name: 'feePay', label: 'Peşin ödeme şekli', type: 'select', options: [{ value: 'nakit', label: 'Nakit' }, { value: 'kart', label: 'Kart' }, { value: 'havale', label: 'Havale/EFT' }] }])}</div></div>
      <div><div class="col" style="position:sticky;top:80px;gap:16px"><div class="price-box"><div class="small" style="opacity:.85">Gönderi ücreti</div><div class="v" id="pv">-</div><div class="small" id="pd"></div></div>
        <button class="btn primary lg block" id="save">${icon('print')} Kabul et ve etiket yazdır</button><div class="card pad small muted">Desi = En × Boy × Yükseklik / 3000. Desi ile kilogramdan büyük olan ücretlendirilir.<br>Tarife: ${K.tiers(st).map(([d, p]) => `${d} desiye kadar ${money(p)}`).join(' · ')} · üzeri desi başı ${money(st.perDesi)}</div></div></div></div>`;
    const read = () => { const sf = NS.readForm($('#sf', el)), rf = NS.readForm($('#rf', el)), pf = NS.readForm($('#pf', el)); const desi = Math.max(Math.ceil(((Number(pf.w) || 0) * (Number(pf.l) || 0) * (Number(pf.h) || 0)) / 3000), Math.ceil(Number(pf.kg) || 0), 1); return { sf, rf, pf, desi }; };
    const calc = () => { const { sf, rf, pf, desi } = read(); const c = sf.cari ? cari(sf.cari) : null; const sh = { desi, pieces: pf.pieces || 1, service: pf.service, region: rf.region, cod: pf.cod || 0 }; const pr = K.price(S(), sh, c); $('#pv', el).textContent = money(pr); $('#pd', el).innerHTML = `${desi} desi · ${K.SERVICE[pf.service][0]} · ${K.REGION[rf.region][0]}${pf.cod ? ` · KT ${money(pf.cod)}` : ''}${c ? ` · %${c.discount} kurumsal indirim` : ''}`; return { sh, pr, c }; };
    el.addEventListener('input', calc); el.addEventListener('change', (e) => { if (e.target.name === 'cari') { const c = cari(e.target.value); if (c) { $('[name=sname]', el).value = c.name; $('[name=sphone]', el).value = c.phone; $('[name=sdistrict]', el).value = c.district; $('[name=payer]', el).value = 'cari'; } else if ($('[name=payer]', el).value === 'cari') $('[name=payer]', el).value = 'pesin'; } calc(); });
    $('#save', el).onclick = () => {
      if (!NS.validate($('#rf', el))) return;
      const { sf, rf, pf, desi } = read(); const { pr } = calc();
      if (pf.payer === 'cari' && !sf.cari) return toast('Cari ödeme için kurumsal müşteri seçin', 'err');
      if (Number(pf.cod) < 0 || Number(pf.pieces) < 0) return toast('Tutar ve parça eksi olamaz', 'err');
      if (String(rf.rphone).replace(/\D/g, '').length < 10) return toast('Alıcı telefonu eksik: takip doğrulaması ve SMS için gerekli', 'err');
      const fee = pf.payer === 'cari' ? { payer: 'cari' } : pf.payer === 'alici' ? { payer: 'alici' } : { payer: 'pesin', feePay: pf.feePay || 'nakit', feeAt: new Date().toISOString(), feeBy: (NS.currentUser || {}).name };
      const sh = db.insert('ships', { ...fee, no: newNo(), at: new Date().toISOString(), branch: pf.branch || '', cari: sf.cari || null, sender: { name: sf.sname || 'Bireysel', phone: sf.sphone, district: sf.sdistrict }, receiver: { name: rf.rname, phone: rf.rphone, city: rf.rcity, district: rf.region === 'sehirici' ? rf.rdistrict : '', address: rf.raddress }, desi, pieces: pf.pieces || 1, service: pf.service, region: rf.region, cod: pf.cod || 0, content: pf.content, price: pr, status: 'kabul', history: [{ at: new Date().toISOString(), status: 'kabul', note: 'Gönderi kabul edildi', user: (NS.currentUser || {}).name }] });
      db.log('Gönderi kabul', `${sh.no} · ${money(pr)}`); toast(`${sh.no} kabul edildi`, 'ok'); printLabel(sh); app.go('gonderiler');
    };
    calc();
  }
  const labelHtml = (sh) => `<div style="border:2px solid #000;width:380px;font-family:Arial;padding:10px;page-break-after:always"><div style="display:flex;justify-content:space-between;align-items:center"><b style="font-size:16px">${esc(S().bizName)}</b><span style="background:#000;color:#fff;padding:2px 8px;font-weight:700">${esc(K.SERVICE[sh.service][0].split(' ')[0].toUpperCase())}</span></div>
      <div style="margin:8px 0">${NS.barcodeSvg(sh.no, { height: 56 })}</div><div style="font-size:11px">GÖNDERİCİ: ${esc(sh.sender.name)} · ${esc(sh.sender.phone || '')}</div><hr>
      <div style="font-size:18px"><b>${esc(sh.receiver.name)}</b></div><div>${esc(sh.receiver.address || '')}</div><div style="font-size:16px"><b>${esc(sh.receiver.district || '')} / ${esc(sh.receiver.city || '')}</b></div><div>${esc(sh.receiver.phone)}</div>
      <hr><div style="display:flex;justify-content:space-between"><span>${sh.desi} desi · ${sh.pieces} parça</span><span>${NS.date(sh.at)}</span></div>${sh.cod ? `<div style="background:#000;color:#fff;text-align:center;padding:4px;margin-top:6px;font-size:16px"><b>KAPIDA TAHSİLAT ${money(sh.cod)}</b></div>` : ''}<div style="display:flex;gap:10px;align-items:center;margin-top:6px">${NS.qrSvg(trackUrl(sh), 70)}<span style="font-size:10px">Takip: ${esc(trackUrl(sh))}</span></div></div>`;
  const printLabel = (sh) => NS.printHtml(labelHtml(sh), { title: sh.no });
  // Belgeler NS.docs üzerinden (kargo etiketi kendi barkod düzeniyle kalır)
  const routeDoc = (c, list) => ({ title: 'Dağıtım listesi', no: c.name, info: [['Plaka', c.plate || ''], ['Gönderi', String(list.length)]], lines: list.map((s) => ({ name: `${s.no} · ${s.receiver.name} · ${s.receiver.phone}`, note: `${s.receiver.address || ''} ${s.receiver.district || ''}`.trim(), qty: 1, price: s.cod || 0, total: s.cod || 0 })), totals: [['Kapıda tahsilat', sum(list, (s) => s.cod), true]], signatures: [{ label: 'Kurye' }, { label: 'Teslim eden' }] });
  const statementDoc = (c, mo, list) => ({ title: 'Aylık gönderi dökümü', no: `${NS.MONTHS[Number(mo.slice(5)) - 1]} ${mo.slice(0, 4)}`, party: { title: 'Müşteri', name: c.name, lines: [c.address, c.taxNo ? 'VKN ' + c.taxNo : ''] }, lines: list.map((s) => ({ name: `${NS.date(s.at)} · ${s.no} · ${s.receiver.name}`, note: `${s.desi} desi · ${K.ST[s.status][0]}`, qty: 1, price: s.price, total: s.price })), totals: [['Toplam (KDV dahil)', r2(sum(list, (s) => s.price)), true]] });
  const payoutDoc = (p) => ({ title: 'Kapıda tahsilat ödeme dökümü', no: p.who, date: p.at, info: [['Yöntem', p.method], ['Referans', p.ref || '']], lines: p.ships.map((s) => ({ name: `${s.no} · ${s.name}`, qty: 1, price: s.amount, total: s.amount })), totals: [['Ödenen', p.total, true]] });
  const primDoc = (c, mo, r) => ({ title: 'Kurye hakediş dökümü', no: c.name, info: [['Dönem', mo], ['Teslim', String(r.n)], ['Birim prim', money(r.rate)]], lines: r.list.slice(0, 500).map((s) => ({ name: `${NS.date(s.at)} · ${s.no}`, qty: 1, price: r.rate, total: r.rate })), totals: [['Toplam prim', r.total, true]], note: 'Bordro ve vergi hesabı içermez.' });
  if (NS.docs) { NS.docs.define('kargo', 'dagitim', { label: 'Dağıtım listesi' }); NS.docs.define('kargo', 'dokum', { label: 'Aylık gönderi dökümü' }); NS.docs.define('kargo', 'kt', { label: 'KT ödeme dökümü' }); NS.docs.define('kargo', 'prim', { label: 'Kurye hakediş dökümü' }); }
  const branches = () => String(S().branches || '').split(',').map((x) => x.trim()).filter(Boolean);
  // Dağıtım sırası önerisi: aynı gün/ekspres önce, alıcının istediği gün, kurye bölge sırası, sonra adres. Elle sıra (stopNo) önceliklidir. Harita mesafesi kullanılmaz: gönderilerde koordinat yok.
  const routeSort = (c, list) => { const sv = { ayni: 0, ekspres: 1, standart: 2 }; const z = (s) => { const i = (c.zone || []).indexOf(s.receiver.district); return i < 0 ? 99 : i; }; const day = (s) => (s.retryDate === today() || (s.pref && s.pref.date === today()) ? 0 : 1); return list.slice().sort((a, b) => (a.stopNo ?? 1e9) - (b.stopNo ?? 1e9) || sv[a.service] - sv[b.service] || day(a) - day(b) || z(a) - z(b) || String(a.receiver.address).localeCompare(String(b.receiver.address), 'tr')); };
  // Kurye primi: ayın teslim edilen gönderisi × kuryenin birim primi (boşsa ayar)
  const primOf = (c, mo) => { const list = db.all('ships', (s) => s.courier === c.id && s.status === 'teslim' && iso(s.history[s.history.length - 1].at).startsWith(mo)); const rate = Number(c.prim) || Number(S().primDefault) || 0; return { list, n: list.length, rate, total: r2(list.length * rate) }; };

  // ---------- Gönderiler ----------
  function shipModal(app, sh) {
    modal({
      title: `${sh.no}`, size: 'wide',
      body: `<div class="grid g2"><div class="col"><div class="row">${stB(sh.status)} ${badge(K.SERVICE[sh.service][0], 'acc')} ${sh.cod ? badge('KT ' + money(sh.cod), 'warn') : ''}</div>
          <div class="card pad"><div class="small muted">Gönderici</div><b>${esc(sh.sender.name)}</b><div class="small">${esc(sh.sender.phone || '')} · ${esc(sh.sender.district || '')}</div><div class="mt">${feeB(sh)}${sh.ebelge ? ' ' + badge(`${sh.ebelge.type} ${sh.ebelge.no}${sh.ebelge.test ? ' · TEST' : ''}`, sh.ebelge.test ? 'warn' : 'ok') : ''}</div></div>
          <div class="card pad"><div class="small muted">Alıcı</div><b>${esc(sh.receiver.name)}</b><div class="small">${esc(sh.receiver.phone)}</div><div class="small muted">${esc(sh.receiver.address || '')} ${esc(sh.receiver.district || '')} / ${esc(sh.receiver.city || '')}</div>${prefTxt(sh) ? `<div class="small mt" style="color:var(--warn);font-weight:600">${esc(prefTxt(sh))}</div>` : ''}${sh.rating ? `<div class="small mt">Alıcı puanı: <span style="color:#f59e0b">${'★'.repeat(sh.rating.stars)}</span></div>` : ''}</div>
          <div class="list-item small"><span class="grow muted">Desi / parça</span>${sh.desi} / ${sh.pieces}</div><div class="list-item small"><span class="grow muted">Ücret</span><b>${money(sh.price)}</b></div><div class="list-item small"><span class="grow muted">Kurye</span>${esc(cour(sh.courier).name)}</div>
          ${sh.signature ? `<div><div class="small muted">Alıcı imzası</div><img src="${sh.signature}" style="max-width:100%;border:1px solid var(--border);border-radius:8px;background:#fff"></div>` : ''}
          ${sh.status === 'teslim' || sh.failGeo ? `<div class="card pad small"><b>Teslim kanıtı</b><div>Konum: ${mapA(sh.status === 'teslim' ? sh.geo : sh.failGeo)}</div>${sh.photo ? `<img src="${sh.photo}" alt="Teslim fotoğrafı" style="max-width:100%;border-radius:8px;margin-top:6px">` : ''}</div>` : ''}
          ${(sh.attempts || 0) >= 3 && sh.status === 'edilemedi' ? `<div class="card pad small" style="border-color:var(--warn)">${icon('alert')} ${sh.attempts} kez teslim edilemedi — göndericiye iade önerilir.</div>` : ''}</div>
        <div><h3 class="mb">Hareketler</h3><div class="tl">${sh.history.slice().reverse().map((h) => `<div class="it"><b>${esc(K.ST[h.status][0])}</b><div class="small">${esc(h.note || '')}</div><div class="small faint">${NS.dt(h.at)}${h.user ? ' · ' + esc(h.user) : ''}</div></div>`).join('')}</div></div></div>`,
      actions: [
        { label: 'Etiket', icon: 'print', onClick: () => printLabel(sh) },
        ...(payerOf(sh) !== 'cari' && (!sh.ebelge || sh.ebelge.test) && NS.ebelge && isAdm() ? [{ label: sh.ebelge ? 'Faturayı yeniden kes' : 'Fatura kes', icon: 'file', onClick: async (c) => { const r = await NS.ebelge.create({ docType: 'e-Arşiv', no: sh.no, buyer: sh.payer === 'alici' ? sh.receiver.name : sh.sender.name, address: sh.payer === 'alici' ? sh.receiver.address : '', district: sh.payer === 'alici' ? sh.receiver.district : sh.sender.district, city: sh.payer === 'alici' ? sh.receiver.city : '', lines: [{ name: `Kargo taşıma hizmeti ${sh.no} (${sh.desi} desi)`, qty: 1, vat: vat(), total: sh.price }], note: `Gönderi ${sh.no}` }); if (r && r.ok) { sh.ebelge = { type: r.type, no: r.no, id: r.id, test: !!r.simulated }; db.save(); c(); app.refresh(); } } }] : []),
        { label: 'Takip linki', icon: 'globe', onClick: () => { navigator.clipboard && navigator.clipboard.writeText(trackUrl(sh)); window.open(trackUrl(sh), '_blank'); } },
        ...(sh.status === 'kabul' ? [{ label: 'Transfer merkezine al', cls: 'primary', onClick: (c) => { setStatus(sh, 'depoda', 'Transfer merkezine ulaştı'); db.save(); c(); app.refresh(); } }] : []),
        // Şehir dışı / bölge dışı gönderiler anlaşmalı kargo firmasına API ile aktarılır
        ...(['kabul', 'depoda'].includes(sh.status) && !sh.partner ? [{ label: 'Anlaşmalı kargoya aktar', icon: 'truck', onClick: async (c) => {
          if (!NS.integ) return; const provs = NS.integ.CONN.kargofirma[4];
          const v = await formModal({ title: 'Anlaşmalı kargo firmasına aktar', fields: [{ name: 'carrier', label: 'Kargo firması', type: 'select', options: Object.values(provs) }] }); if (!v) return;
          const r = await NS.integ.call('kargofirma', 'gonderi-olustur', { carrier: v.carrier, ref: sh.no, desi: sh.desi, pieces: sh.pieces, cod: sh.cod || 0, receiver: sh.receiver, sender: sh.sender }, { silent: true });
          // Firmanın gönderi API'si bağlı değilse (yalnızca takip) gönderi firmada açılır, takip numarası elle girilir
          // Simülasyondaki iç referans takip numarası değildir; yalnızca firmanın döndürdüğü takip no kabul edilir
          let trk = r && r.ok && !r.simulated && r.data && r.data.tracking ? r.data.tracking : null;
          if (r && r.simulated) toast('TEST: kargo bağlantısı simülasyonda, firmada gönderi oluşturulmadı', 'warn');
          if (!trk) { if (r && !r.ok && r.error && !r.unsupported && !r.disabled) return toast(r.error, 'err'); trk = await NS.prompt(`${v.carrier} gönderisini firmanın şubesinde / panelinde oluşturup verilen takip numarasını yazın`, '', { title: 'Takip numarası' }); if (!trk) return; }
          sh.partner = { carrier: v.carrier, tracking: String(trk).trim() }; setStatus(sh, 'depoda', `${v.carrier} firmasına aktarıldı · takip ${sh.partner.tracking}`); db.save(); c(); app.refresh();
        } }] : []),
        ...(sh.partner ? [{ label: NS.integ && NS.integ.trackOf(sh.partner.carrier) ? `${sh.partner.carrier} takip` : `${sh.partner.carrier} durumu`, icon: 'refresh', onClick: async () => { const r = await NS.integ.call('kargofirma', 'durum-sorgu', { carrier: sh.partner.carrier, tracking: sh.partner.tracking }); if (r && r.ok && r.data && r.data.delivered) { partnerDone(sh); db.save(); app.refresh(); } } }] : []),
        // Firma durumu API'den gelmiyorsa (takip sayfası) teslim elle işlenir; KT ve alıcı ödemeli ücret firmadan alınacak para olur
        ...(sh.partner && ['kabul', 'depoda'].includes(sh.status) ? [{ label: 'Firma teslim etti', icon: 'check', onClick: async (c) => { if (!(await confirm(`${sh.partner.carrier} takip sayfasında teslim edildiğini gördünüz mü?`))) return; partnerDone(sh); db.save(); c(); app.refresh(); } }] : []),
        ...(sh.status === 'edilemedi' ? [{ label: 'Tekrar dağıtıma', onClick: (c) => { sh.retryDate = null; setStatus(sh, 'depoda', 'Yeniden dağıtım için depoya alındı'); db.save(); c(); app.refresh(); } }, { label: 'Göndericiye iade', cls: 'danger', onClick: (c) => { setStatus(sh, 'iade'); db.save(); c(); app.refresh(); } }] : []),
      ],
    });
  }
  // Anlaşmalı firma teslim etti: kapıda tahsilat ve alıcı ödemeli ücret firmadan tahsil edilecek olarak mutabakata düşer
  function partnerDone(sh) { if (sh.cod) { sh.codCollected = sh.cod; sh.codPay = 'havale'; } if (sh.payer === 'alici' && !sh.feeCollected) { sh.feeCollected = sh.price; sh.feePay = 'havale'; } setStatus(sh, 'teslim', `${sh.partner.carrier} teslim etti`); }
  // Excel/CSV'den toplu gönderi: E-ticaret "Kargo listesi" dosyası da bu sütunlarla gelir. Aynı referans ikinci kez alınmaz.
  async function importShips(app) {
    let f; try { f = await NS.readSheet(); } catch (e) { return toast(e.message, 'err'); } if (!f) return; if (!f.rows.length) return toast('Dosyada satır yok', 'err');
    const nrm = (x) => String(x || '').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9çğıöşü]/g, ''); const numOf = (v) => { if (typeof v === 'number') return v; const t = String(v == null ? '' : v).trim(); return t === '' ? 0 : Number(t.includes(',') ? t.replace(/\./g, '').replace(',', '.') : t); };
    const AL = { name: ['alıcı', 'alıcıadı', 'adsoyad', 'müşteri'], phone: ['telefon', 'tel', 'gsm', 'cep'], city: ['şehir', 'il'], district: ['ilçe'], address: ['adres', 'açıkadres'], desi: ['desi'], pieces: ['parça', 'parçaadedi', 'adet'], cod: ['kapıdatahsilat', 'tahsilat', 'kt'], ref: ['referans', 'siparişno', 'sipariş', 'ref'], content: ['içerik'] };
    const keys = [...new Set(f.rows.flatMap((r) => Object.keys(r)))]; const col = {}; Object.entries(AL).forEach(([k, al]) => { const h = keys.find((x) => al.includes(nrm(x))); if (h) col[k] = h; });
    const miss = ['name', 'phone', 'address'].filter((k) => !col[k]); if (miss.length) return toast(`Gerekli sütun bulunamadı: ${miss.map((k) => AL[k][0]).join(', ')}`, 'err');
    const v = await formModal({ title: `Toplu gönderi — ${f.rows.length} satır`, fields: [{ name: 'cari', label: 'Kurumsal müşteri', type: 'select', empty: 'Yok (bireysel)', options: db.all('caris').map((c) => ({ value: c.id, label: c.name })) }, { name: 'payer', label: 'Gönderi ücretini kim öder', type: 'select', options: Object.entries(PAYER).map(([value, label]) => ({ value, label })) }, { name: 'service', label: 'Hizmet', type: 'select', options: Object.entries(K.SERVICE).map(([value, x]) => ({ value, label: x[0] })) }, { name: 'home', label: 'Şehir içi sayılan il', value: S().homeCity || 'İstanbul' }, { name: 'far', label: 'Şehir dışı bölge', type: 'select', options: [{ value: 'uzak', label: K.REGION.uzak[0] }, { value: 'bolge', label: K.REGION.bolge[0] }] }] }); if (!v) return;
    if (v.payer === 'cari' && !v.cari) return toast('Cari ödeme için kurumsal müşteri seçin', 'err');
    const c = v.cari ? cari(v.cari) : null; const errs = []; const plan = []; const seen = new Set(); let dup = 0; const refs = new Set(db.all('ships', (s) => s.ref && (s.cari || null) === (v.cari || null)).map((s) => s.ref));
    f.rows.forEach((r, n) => { const g = (k) => (col[k] ? String(r[col[k]] == null ? '' : r[col[k]]).trim() : ''); const name = g('name'), phone = g('phone'), address = g('address'), ref = g('ref'); if (!name || !address) return errs.push(`Satır ${n + 2}: alıcı veya adres boş`); if (phone.replace(/\D/g, '').length < 10) return errs.push(`Satır ${n + 2}: telefon eksik`); if (ref && (refs.has(ref) || seen.has(ref))) { dup++; return; } if (ref) seen.add(ref); const desi = Math.max(1, Math.ceil(numOf(g('desi')) || 1)); const pieces = Math.max(1, Math.floor(numOf(g('pieces')) || 1)); const cod = numOf(g('cod')); if (!(cod >= 0)) return errs.push(`Satır ${n + 2}: tahsilat geçersiz`); const city = g('city') || v.home; const region = nrm(city) === nrm(v.home) ? 'sehirici' : v.far; plan.push({ ref, name, phone, address, city, district: region === 'sehirici' ? g('district') : '', desi, pieces, cod: r2(cod), region, content: g('content') }); });
    if (!plan.length) return toast(errs[0] || (dup ? `${dup} satır daha önce aktarılmış` : 'Aktarılacak satır yok'), 'err');
    if (!(await confirm(`${plan.length} gönderi açılacak${dup ? `, ${dup} tekrar atlanacak` : ''}${errs.length ? `, ${errs.length} hatalı satır atlanacak (ilki: ${errs[0]})` : ''}. Toplam ${money(sum(plan, (x) => K.price(S(), { ...x, service: v.service }, c)))}. Devam edilsin mi?`))) return;
    const now = new Date().toISOString(); const made = plan.map((x) => { const sh = { desi: x.desi, pieces: x.pieces, service: v.service, region: x.region, cod: x.cod }; const price = K.price(S(), sh, c); return db.insert('ships', { ...sh, no: newNo(), at: now, ref: x.ref, cari: v.cari || null, payer: v.payer, ...(v.payer === 'pesin' ? { feePay: 'nakit', feeAt: now, feeBy: me() } : {}), sender: { name: c ? c.name : 'Toplu aktarım', phone: c ? c.phone : '', district: c ? c.district : '' }, receiver: { name: x.name, phone: x.phone, city: x.city, district: x.district, address: x.address }, content: x.content, price, status: 'kabul', history: [{ at: now, status: 'kabul', note: 'Excel ile toplu kabul', user: me() }] }, true); });
    db.log('Excel aktarımı', `${made.length} gönderi`); db.save(); toast(`${made.length} gönderi açıldı`, 'ok'); if (await confirm(`${made.length} etiket yazdırılsın mı?`)) NS.printHtml(made.map(labelHtml).join(''), { title: 'Etiketler' }); app.refresh();
  }
  function shipsPage(el, p, app) {
    let q = '', f = p || 'aktif';
    el.innerHTML = pageHead('Gönderiler', 'Tüm gönderiler ve durumları', `<button class="btn" id="ex" title="Listeyi indir" aria-label="Listeyi indir">${icon('download')}</button><button class="btn" id="imp">${icon('upload')} Excel'den gönderi al</button><a class="btn primary" href="#/kabul">${icon('plus')} Gönderi kabul</a>`) + `<div class="card"><div class="card-h">${NS.searchBox('q', 'Takip no, alıcı, telefon...')}<div class="seg">${[['aktif', 'Aktif'], ['kabul', 'Kabul'], ['depoda', 'Depoda'], ['dagitimda', 'Dağıtımda'], ['edilemedi', 'Edilemedi'], ['teslim', 'Teslim'], ['all', 'Tümü']].map(([v, l]) => `<button data-f="${v}" class="${v === f ? 'active' : ''}">${l}</button>`).join('')}</div></div><div id="t"></div></div>`;
    const rows = () => db.all('ships', (s) => (f === 'all' || (f === 'aktif' ? ['kabul', 'depoda', 'dagitimda', 'edilemedi'].includes(s.status) : s.status === f)) && NS.match(q, s.no, s.receiver.name, s.receiver.phone, s.sender.name)).sort((a, b) => b.at.localeCompare(a.at));
    const retB = (s) => ((s.attempts || 0) >= 3 && s.status === 'edilemedi' ? ' ' + badge('İade önerilir', 'warn') : '');
    const draw = () => { const r = rows();
      if (window.matchMedia('(max-width: 700px)').matches) { $('#t', el).innerHTML = r.length ? `<div class="card-b">${r.slice(0, 300).map((s) => `<div class="list-item" data-act="v" data-id="${s.id}" style="cursor:pointer;align-items:flex-start"><div class="grow"><b class="mono">${esc(s.no)}</b><div class="small">${esc(s.receiver.name)} · ${esc(s.receiver.district || s.receiver.city || '')}</div><div class="small faint">${NS.dt(s.at)}${s.courier ? ' · ' + esc(cour(s.courier).name.split(' ')[0]) : ''}</div><div class="mt">${stB(s.status)}${retB(s)}${s.cod ? ' ' + badge('KT ' + money(s.cod), 'warn') : ''}</div></div><b>${money(s.price)}</b></div>`).join('')}</div><div class="card-b small faint">${r.length} gönderi</div>` : `<div class="empty">${icon('truck')}<div>Gönderi yok</div></div>`; return; }
      $('#t', el).innerHTML = table({ rows: r.slice(0, 300), emptyIcon: 'truck', columns: [{ label: 'Takip no', render: (s) => `<b class="mono">${esc(s.no)}</b><div class="small faint">${NS.dt(s.at)}</div>` }, { label: 'Gönderici', render: (s) => esc(s.sender.name) }, { label: 'Alıcı', render: (s) => `${esc(s.receiver.name)}<div class="small faint">${esc(s.receiver.district || s.receiver.city)}</div>` }, { label: 'Hizmet', render: (s) => `${esc(K.SERVICE[s.service][0].split(' ')[0])} · ${s.desi} ds` }, { label: 'KT', cls: 'right', render: (s) => (s.cod ? money(s.cod) : '-') }, { label: 'Kurye', render: (s) => esc(s.courier ? cour(s.courier).name.split(' ')[0] : '-') }, { label: 'Durum', render: (s) => stB(s.status) + retB(s) }, { label: 'Ücret', cls: 'right', render: (s) => `${money(s.price)}<div class="mt">${feeB(s)}</div>` }], actions: [{ icon: 'eye', act: 'v' }], foot: `${r.length} gönderi · ${money(sum(r, (s) => s.price))}` }); };
    $('#q', el).oninput = (e) => { q = e.target.value; draw(); };
    on(el, 'click', '[data-f]', (e, b) => { f = b.dataset.f; $$('[data-f]', el).forEach((x) => x.classList.toggle('active', x === b)); draw(); });
    on(el, 'click', '[data-act=v]', (e, b) => shipModal(app, db.get('ships', b.dataset.id)));
    $('#imp', el).onclick = () => importShips(app);
    $('#ex', el).onclick = () => NS.csv('gonderiler', rows(), [{ key: 'no', label: 'Takip' }, { label: 'Tarih', value: (s) => NS.dt(s.at) }, { label: 'Alıcı', value: (s) => s.receiver.name }, { label: 'İlçe', value: (s) => s.receiver.district }, { label: 'Durum', value: (s) => K.ST[s.status][0] }, { key: 'price', label: 'Ücret' }, { key: 'cod', label: 'KT' }]);
    draw();
  }

  // ---------- Zimmet / dağıtım ----------
  function assignPage(el, p, app) {
    // Alıcının takip sayfasından istediği yeniden teslimat günü geldiyse gönderi kendiliğinden havuza düşer
    const due = (s) => s.status === 'edilemedi' && s.retryDate && s.retryDate <= today();
    const pool = db.all('ships', (s) => (['kabul', 'depoda'].includes(s.status) || due(s)) && !s.partner && s.region === 'sehirici');
    const byD = NS.groupBy(pool, (s) => s.receiver.district || '-');
    el.innerHTML = pageHead('Zimmet & Dağıtım', 'Depodaki şehir içi gönderileri bölgeye göre kuryelere zimmetleyin', `<button class="btn" id="gps">${icon('map')} Kurye konumları</button><button class="btn" id="auto">${icon('zap')} Bölgeye göre otomatik zimmetle</button>`) + `
      <div class="grid g-21"><div class="card"><div class="card-h"><h3>Dağıtım bekleyen (${pool.length})</h3></div>${Object.entries(byD).sort((a, b) => b[1].length - a[1].length).map(([d, list]) => `<div class="card-b" style="border-bottom:1px solid var(--border)"><div class="row mb"><b class="grow">${icon('map')} ${esc(d)} <span class="faint">(${list.length})</span></b><span class="small muted">Önerilen: ${esc((suggest(list[0]) || { name: '-' }).name)}</span></div>${list.slice(0, 200).map((s) => `<div class="list-item small"><input type="checkbox" data-pick="${s.id}" aria-label="Seç"><b class="mono">${esc(s.no)}</b><span class="grow">${esc(s.receiver.name)} · ${esc(s.receiver.address || '')}</span>${due(s) ? badge('Yeniden teslimat', 'warn') : ''}${s.cod ? badge('KT', 'warn') : ''}${badge(K.SERVICE[s.service][0].split(' ')[0], s.service === 'ayni' ? 'err' : '')}</div>`).join('')}${list.length > 200 ? `<div class="small faint">İlk 200 gösteriliyor; otomatik zimmet tümünü kapsar</div>` : ''}</div>`).join('') || '<div class="empty">Dağıtım bekleyen gönderi yok</div>'}
        <div class="card-b row"><select class="input" id="kc">${db.all('couriers').map((c) => `<option value="${c.id}">${esc(c.name)} — ${esc(c.zone.join(', '))}</option>`).join('')}</select><button class="btn primary" id="as">${icon('truck')} Seçilenleri zimmetle</button></div></div>
      <div class="col" style="gap:12px">${db.all('couriers').map((c) => { const mine = db.all('ships', (s) => s.courier === c.id && s.status === 'dagitimda'); return `<div class="card pad"><div class="row nw"><div class="avatar">${esc(NS.initials(c.name))}</div><div class="grow"><b>${esc(c.name)}</b><div class="small faint">${esc(c.vehicle)} · ${esc(c.plate)}</div></div>${badge(mine.length + ' paket', mine.length ? 'acc' : '')}</div><div class="small muted mt">${esc(c.zone.join(', '))}</div>${mine.length ? `<button class="btn sm mt" data-route="${c.id}">${icon('print')} Dağıtım listesi</button>` : ''}</div>`; }).join('')}</div></div>`;
    const out = (s, cid) => { s.courier = cid; s.retryDate = null; s.stopNo = null; if (s.status === 'kabul') setStatus(s, 'depoda', 'Transfer merkezine ulaştı'); setStatus(s, 'dagitimda', `Kurye ${cour(cid).name} dağıtıma çıkardı`); };
    // İsteğe bağlı: dağıtıma çıkınca alıcıya SMS (sonuç NS.smsBatch özetinde gerçek durumuyla görünür)
    const notify = (list) => { if (S().smsOnDispatch) NS.smsBatch(db, list.map((s) => ({ to: s.receiver.phone, name: s.receiver.name, text: `${S().bizName}: ${s.no} nolu gönderiniz bugün dağıtımda. Takip ve teslimat tercihi: ${trackUrl(s)}` })), 'dağıtım bildirimi'); };
    const assign = (ids, cid) => { const list = ids.map((id) => db.get('ships', id)); list.forEach((s) => out(s, cid)); db.save(); toast(`${ids.length} gönderi zimmetlendi`, 'ok'); notify(list); app.refresh(); };
    $('#gps', el).onclick = async () => {
      if (!NS.integ) return; const cs = db.all('couriers'); const r = await NS.integ.call('gps', 'konumlar', { plates: cs.map((c) => c.plate) }); if (!r || !r.ok) return;
      // Konum uydurulmaz: servis simülasyondaysa veya konum dönmediyse gösterilecek bir şey yoktur
      if (r.simulated || !(r.data && Array.isArray(r.data.positions) && r.data.positions.length)) return toast(r.simulated ? 'TEST: araç takip servisi simülasyonda, gerçek konum yok' : 'Araç takip servisi konum döndürmedi', 'warn');
      const pos = r.data.positions;
      modal({ title: 'Kurye konumları', size: 'wide', body: table({ rows: pos.map((x, i) => ({ ...x, id: i })), columns: [{ label: 'Kurye', render: (x) => esc((cs.find((c) => c.plate === x.plate) || {}).name || x.plate) }, { label: 'Plaka', render: (x) => esc(x.plate) }, { label: 'Hız', cls: 'right', render: (x) => `${x.speed} km/s` }, { label: 'Zaman', render: (x) => NS.time(x.at) }, { label: 'Harita', render: (x) => `<a class="btn sm" target="_blank" rel="noopener" href="https://www.google.com/maps?q=${x.lat},${x.lng}">${icon('map')} Aç</a>` }] }) });
    };
    $('#as', el).onclick = () => { const ids = $$('[data-pick]:checked', el).map((c) => c.dataset.pick); if (!ids.length) return toast('Gönderi seçin', 'err'); assign(ids, $('#kc', el).value); };
    $('#auto', el).onclick = () => { const list = []; pool.forEach((s) => { const c = suggest(s); if (c) { out(s, c.id); list.push(s); } }); db.save(); toast(`${list.length} gönderi bölgesine göre zimmetlendi${list.length < pool.length ? ` · ${pool.length - list.length} gönderinin bölgesinde kurye yok` : ''}`, list.length ? 'ok' : 'warn'); notify(list); app.refresh(); };
    on(el, 'click', '[data-route]', (e, b) => { const c = cour(b.dataset.route); NS.docs.print('dagitim', routeDoc(c, routeSort(c, db.all('ships', (s) => s.courier === c.id && s.status === 'dagitimda')))); });
  }

  // ---------- Kurye ekranı ----------
  let viewCourier = null;
  function courierPage(el, p, app) {
    viewCourier = myCourier() || viewCourier || 'k1';
    const c = cour(viewCourier);
    const list = routeSort(c, db.all('ships', (s) => s.courier === c.id && s.status === 'dagitimda'));
    const doneToday = db.all('ships', (s) => s.courier === c.id && ['teslim', 'edilemedi'].includes(s.status) && iso(s.history[s.history.length - 1].at) === today());
    el.innerHTML = pageHead('Kurye Ekranı', `${esc(c.name)} · ${esc(c.vehicle)} ${esc(c.plate || '')}`, myCourier() ? '' : `<select class="input" id="kc" style="max-width:220px">${db.all('couriers').map((x) => `<option value="${x.id}" ${x.id === c.id ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select>`) + `
      <div class="grid g3 mb">${kpi('Teslim edilecek', list.length, 'truck', 'info')}${kpi('Bugün teslim', doneToday.filter((s) => s.status === 'teslim').length, 'check', 'ok')}${kpi('Üzerimdeki para', money(sum(db.all('ships', (s) => s.courier === c.id && cash(s) > 0 && !s.codSettled), cash)), 'cash', 'warn', '<div class="small faint">Kapıda tahsilat + alıcı ödemeli ücret</div>')}</div>
      ${list.map((s, i) => `<div class="stop"><div class="row nw"><div class="n">${i + 1}</div><div class="grow"><b>${esc(s.receiver.name)}</b> <span class="mono small faint">${esc(s.no)}</span><div class="small">${esc(s.receiver.address || '')} · <b>${esc(s.receiver.district)}</b></div>${prefTxt(s) ? `<div class="small" style="color:var(--warn);font-weight:600">${icon('alert')} ${esc(prefTxt(s))}</div>` : ''}</div>${s.cod ? badge('Tahsil: ' + money(s.cod), 'warn') : ''}</div>
        <div class="row mt"><a class="btn sm" href="tel:${esc(String(s.receiver.phone).replace(/\s/g, ''))}">${icon('phone')} Ara</a><a class="btn sm" target="_blank" rel="noopener" href="https://www.google.com/maps/search/${encodeURIComponent(`${s.receiver.address || ''} ${s.receiver.district} İstanbul`)}">${icon('map')} Yol tarifi</a>${i ? `<button class="btn sm ghost" data-up="${s.id}" title="Sırayı yukarı al" aria-label="Sırayı yukarı al">↑</button>` : ''}<span class="grow"></span><button class="btn sm danger" data-fail="${s.id}">Teslim edilemedi</button><button class="btn sm ok" data-ok="${s.id}">${icon('check')} Teslim et</button></div></div>`).join('') || `<div class="card pad empty">${icon('check')}<div>Dağıtımda paketiniz yok</div></div>`}`;
    if ($('#kc', el)) $('#kc', el).onchange = (e) => { viewCourier = e.target.value; app.refresh(); };
    on(el, 'click', '[data-ok]', (e, b) => { const s = db.get('ships', b.dataset.ok); if (s.status !== 'dagitimda') return app.refresh(); deliver(app, s); });
    on(el, 'click', '[data-up]', (e, b) => { const i = list.findIndex((s) => s.id === b.dataset.up); if (i < 1) return; [list[i - 1], list[i]] = [list[i], list[i - 1]]; list.forEach((s, n) => { s.stopNo = n; }); db.save(); app.refresh(); });
    on(el, 'click', '[data-fail]', async (e, b) => { const s = db.get('ships', b.dataset.fail); if (s.status !== 'dagitimda') return app.refresh(); const v = await formModal({ title: 'Teslim edilemedi', fields: [{ name: 'reason', label: 'Neden', type: 'select', options: K.FAIL }, { name: 'note', label: 'Not' }] }); if (!v) return; const geo = await here(); s.failReason = v.reason; s.failGeo = geo; s.attempts = (s.attempts || 0) + 1; setStatus(s, 'edilemedi', v.reason + (v.note ? ' — ' + v.note : '') + (geo ? ` · konum ${geo.lat}, ${geo.lng}` : ' · konum alınamadı')); db.save(); const m = await smsTo(s.receiver.phone, `${S().bizName}: ${s.no} nolu gönderiniz teslim edilemedi (${v.reason}). Yeniden teslim için: ${S().bizPhone}. Takip: ${trackUrl(s)}`); toast(`Kaydedildi · ${m}${s.attempts >= 3 ? ' · 3. deneme: iade önerilir' : ''}`, 'warn'); app.refresh(); });
  }
  function deliver(app, s) {
    modal({
      title: `Teslim — ${s.receiver.name}`,
      body: `<div class="field mb"><label>Teslim alan</label><input class="input" id="dn" value="${esc(s.receiver.name)}"></div><div class="field mb"><label>Yakınlık</label><select class="input" id="dr"><option>Kendisi</option><option>Aile bireyi</option><option>Komşu</option><option>Kapıcı / görevli</option><option>İş arkadaşı</option></select></div>
        ${s.cod || (s.payer === 'alici' && !s.feeCollected) ? `<div class="card pad mb" style="background:var(--warn-soft);border:0"><b>Kapıda alınacak: ${money((s.cod || 0) + (s.payer === 'alici' && !s.feeCollected ? s.price : 0))}</b>${s.cod && s.payer === 'alici' ? `<div class="small">${money(s.cod)} ürün bedeli + ${money(s.price)} kargo ücreti</div>` : s.payer === 'alici' ? '<div class="small">Kargo ücreti (alıcı ödemeli)</div>' : ''}<div class="row mt"><label class="check"><input type="radio" name="cp" value="nakit" checked> Nakit</label><label class="check"><input type="radio" name="cp" value="kart"> Kart (POS)</label></div></div>` : ''}
        <div class="field mb"><label>Teslim fotoğrafı (isteğe bağlı)</label><input class="input" type="file" accept="image/*" capture="environment" id="ph"></div>
        <div class="small faint mb">Teslim anının konumu (izin verilirse) kanıt olarak kaydedilir.</div>
        <div class="field"><label>Alıcı imzası</label><canvas class="sig" id="sig" width="600" height="220"></canvas><button class="btn sm ghost mt" id="cl">Temizle</button></div>`,
      onOpen: (b) => {
        const cv = $('#sig', b); const ctx = cv.getContext('2d'); ctx.lineWidth = 3; ctx.lineCap = 'round'; ctx.strokeStyle = '#111';
        let drawing = false; const pos = (e) => { const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) * (cv.width / r.width), (e.clientY - r.top) * (cv.height / r.height)]; };
        cv.onpointerdown = (e) => { drawing = true; cv.dataset.signed = '1'; ctx.beginPath(); ctx.moveTo(...pos(e)); cv.setPointerCapture(e.pointerId); };
        cv.onpointermove = (e) => { if (!drawing) return; ctx.lineTo(...pos(e)); ctx.stroke(); };
        cv.onpointerup = () => { drawing = false; };
        $('#cl', b).onclick = () => { ctx.clearRect(0, 0, cv.width, cv.height); delete cv.dataset.signed; };
      },
      actions: [{ label: 'Vazgeç' }, { label: 'Teslimi onayla', cls: 'ok', icon: 'check', onClick: async (c, b) => {
        const cv = $('#sig', b); if (!cv.dataset.signed) return toast('Alıcı imzası gerekli', 'err');
        const btn = b.closest('.ns-modal') && b.closest('.ns-modal').querySelector('.ns-modal-f .ok'); if (btn) btn.disabled = true;
        const [geo, photo] = await Promise.all([here(), shrink(($('#ph', b).files || [])[0])]);
        s.deliveredTo = `${$('#dn', b).value} (${$('#dr', b).value})`; s.signature = cv.toDataURL('image/png'); s.geo = geo; if (photo) s.photo = photo;
        const pay = ($('[name=cp]:checked', b) || {}).value;
        if (s.cod) { s.codCollected = s.cod; s.codPay = pay; }
        if (s.payer === 'alici' && !s.feeCollected) { s.feeCollected = s.price; s.feePay = pay; }
        setStatus(s, 'teslim', `Teslim alan: ${s.deliveredTo}${geo ? ` · konum ${geo.lat}, ${geo.lng}` : ' · konum alınamadı'}${photo ? ' · fotoğraf' : ''}`); db.save(); c(); NS.beep(1300, 120); toast('Teslim edildi', 'ok'); app.refresh();
      } }],
    });
  }

  // ---------- Mutabakat ----------
  function settlePage(el, p, app) {
    const open = db.all('ships', (s) => cash(s) > 0 && !s.codSettled);
    const byC = NS.groupBy(open, (s) => s.courier || (s.partner ? 'partner' : ''));
    const nak = (v) => sum(v.filter((s) => !['kart', 'havale'].includes(s.codPay)), (s) => s.codCollected || 0) + sum(v.filter((s) => !['kart', 'havale'].includes(s.feePay) && s.payer === 'alici'), (s) => s.feeCollected || 0);
    const kart = (v) => sum(v, cash) - nak(v);
    const owed = NS.groupBy(db.all('ships', (s) => s.codSettled && s.codCollected && !s.codPaidOut), (s) => s.cari || 'bireysel');
    el.innerHTML = pageHead('Kapıda Tahsilat Mutabakatı', 'Kuryelerin topladığı paranın teslim alınması ve göndericilere ödeme') + `
      <div class="grid g3 mb">${kpi('Kuryelerdeki para', money(sum(open, cash)), 'cash', 'warn', '<div class="small faint">Kapıda tahsilat + alıcı ödemeli ücret</div>')}${kpi('Göndericilere ödenecek', money(sum(Object.values(owed).flat(), (s) => s.codCollected)), 'wallet', 'info')}${kpi('Bu ay tahsil edilen', money(sum(db.all('ships', (s) => s.codCollected && s.at.slice(0, 7) === today().slice(0, 7)), (s) => s.codCollected)), 'trend', 'ok')}</div>
      <div class="grid g2"><div class="card"><div class="card-h"><h3>1) Kuryelerden teslim al</h3></div>${table({ rows: Object.entries(byC).map(([k, v]) => ({ id: k, k, v })), empty: 'Kuryelerde bekleyen para yok', columns: [{ label: 'Kurye', render: (r) => `<b>${esc(cour(r.k).name)}</b>` }, { label: 'Paket', cls: 'right', render: (r) => r.v.length }, { label: 'Nakit', cls: 'right', render: (r) => money(nak(r.v)) }, { label: 'Kart', cls: 'right', render: (r) => money(kart(r.v)) }, { label: 'Toplam', cls: 'right', render: (r) => `<b>${money(sum(r.v, cash))}</b>` }], actions: [{ label: 'Say ve teslim al', act: 'set' }] })}</div>
      <div class="card"><div class="card-h"><h3>2) Göndericilere öde</h3></div>${table({ rows: Object.entries(owed).map(([k, v]) => ({ id: k, k, v })), empty: 'Ödenecek tutar yok', columns: [{ label: 'Gönderici', render: (r) => `<b>${esc(r.k === 'bireysel' ? 'Bireysel göndericiler' : (cari(r.k) || {}).name)}</b>` }, { label: 'Paket', cls: 'right', render: (r) => r.v.length }, { label: 'Tutar', cls: 'right', render: (r) => `<b>${money(sum(r.v, (s) => s.codCollected || 0))}</b>` }], actions: [{ label: 'Ödendi', act: 'pay' }] })}</div></div>
      <div class="card mt"><div class="card-h"><h3>Kurye teslim kayıtları</h3></div>${table({ rows: (db.data.cashins || []).slice(0, 30), empty: 'Henüz kayıt yok', columns: [{ label: 'Tarih', render: (x) => NS.dt(x.at) }, { label: 'Kurye', render: (x) => esc(cour(x.courier).name) }, { label: 'Beklenen', cls: 'right', render: (x) => money(x.expected) }, { label: 'Sayılan', cls: 'right', render: (x) => money(x.counted) }, { label: 'Fark', cls: 'right', render: (x) => (Math.abs(x.diff) < 0.005 ? badge('Tam', 'ok') : `<b style="color:var(--err)">${money(x.diff)}</b>`) }, { label: 'Teslim alan', render: (x) => esc(x.by || '') }] })}</div>
      <div class="card mt"><div class="card-h"><h3>Göndericilere yapılan ödemeler</h3></div>${table({ rows: (db.data.codPayouts || []).slice(0, 30), empty: 'Henüz ödeme yok', columns: [{ label: 'Tarih', render: (x) => NS.dt(x.at) }, { label: 'Gönderici', render: (x) => esc(x.who) }, { label: 'Paket', cls: 'right', render: (x) => x.ships.length }, { label: 'Yöntem', render: (x) => esc(x.method) }, { label: 'Tutar', cls: 'right', render: (x) => `<b>${money(x.total)}</b>` }], actions: [{ icon: 'print', act: 'pp', title: 'Döküm' }] })}</div>`;
    on(el, 'click', '[data-act]', async (e, b) => {
      const k = b.dataset.id;
      if (b.dataset.act === 'pp') { const x = (db.data.codPayouts || []).find((y) => y.id === k); if (x) NS.docs.print('kt', payoutDoc(x)); return; }
      if (b.dataset.act === 'set') {
        // Kuryeden alınan para sayılır: nakit sayılan, kart POS raporundan; fark kayda geçer
        const v = byC[k] || []; const en = nak(v), ek = kart(v);
        const f = await formModal({ title: `${cour(k).name} — para teslimi`, fields: [{ type: 'section', label: `Beklenen: nakit ${money(en)} · kart ${money(ek)} · ${v.length} gönderi` }, { name: 'cash', label: 'Sayılan nakit (₺)', type: 'number', step: '0.01', required: true }, { name: 'card', label: 'POS raporundaki kart toplamı (₺)', type: 'number', step: '0.01', value: ek }, { name: 'note', label: 'Not (fark varsa açıklama)' }] }); if (!f) return;
        const counted = Math.round(((Number(f.cash) || 0) + (Number(f.card) || 0)) * 100) / 100; const diff = Math.round((counted - en - ek) * 100) / 100;
        if (Math.abs(diff) >= 0.005 && !f.note) return toast(`Fark ${money(diff)} — açıklama yazın`, 'err');
        v.forEach((s) => { s.codSettled = true; }); db.data.cashins = [{ id: NS.uid(), at: new Date().toISOString(), courier: k, n: v.length, expected: Math.round((en + ek) * 100) / 100, counted, diff, note: f.note || '', by: (NS.currentUser || {}).name || '' }, ...(db.data.cashins || [])];
        db.log('Kuryeden para teslim alındı', `${cour(k).name} · ${money(counted)}${diff ? ' · fark ' + money(diff) : ''}`); toast(Math.abs(diff) < 0.005 ? 'Teslim alındı, fark yok' : `Teslim alındı · fark ${money(diff)} kaydedildi`, Math.abs(diff) < 0.005 ? 'ok' : 'warn');
      } else {
        // Göndericiye ödeme: yöntem ve dekont no ile kayda geçer, döküm yazdırılır
        const list = owed[k] || []; const who = k === 'bireysel' ? 'Bireysel göndericiler' : (cari(k) || {}).name || k; const total = r2(sum(list, (s) => s.codCollected || 0));
        const v = await formModal({ title: `${who} — KT ödemesi`, fields: [{ type: 'section', label: `${list.length} gönderi · ${money(total)}` }, { name: 'method', label: 'Ödeme yöntemi', type: 'select', options: ['Havale/EFT', 'Nakit'] }, { name: 'ref', label: 'Dekont / referans no' }] }); if (!v) return;
        const at = new Date().toISOString(); list.forEach((s) => { s.codPaidOut = true; s.codPaidAt = at; }); const rec = { id: NS.uid(), at, who, k, method: v.method, ref: v.ref || '', total, by: me(), ships: list.map((s) => ({ no: s.no, name: s.receiver.name, amount: s.codCollected })) };
        db.data.codPayouts = [rec, ...(db.data.codPayouts || [])]; db.log('KT göndericiye ödendi', `${who} · ${money(total)}`); toast('Ödeme kaydedildi', 'ok'); db.save(); NS.docs.print('kt', payoutDoc(rec));
      }
      db.save(); app.refresh();
    });
  }

  // ---------- Özet / cari / tarife / raporlar ----------
  function dashboard(el, p, app) {
    const all = db.all('ships'); const t = today();
    const todayAcc = all.filter((s) => iso(s.at) === t);
    const done7 = all.filter((s) => ['teslim', 'edilemedi'].includes(s.status) && s.at > addDays(new Date(), -7).toISOString());
    const rate = done7.length ? Math.round((done7.filter((s) => s.status === 'teslim').length / done7.length) * 100) : 0;
    const ser = NS.dailySeries(all, 14, 'at', () => 1);
    el.innerHTML = pageHead(S().bizName, NS.dateLong(new Date()), `<a class="btn" href="#/zimmet">${icon('truck')} Zimmet</a><a class="btn primary" href="#/kabul">${icon('plus')} Gönderi kabul</a>`) + `
      <div class="grid g4 mb">${kpi('Bugün kabul', todayAcc.length, 'box', '', `<div class="small faint">${money(sum(todayAcc, (s) => s.price))}</div>`)}${kpi('Dağıtımda', all.filter((s) => s.status === 'dagitimda').length, 'truck', 'info')}${kpi('Depoda bekleyen', all.filter((s) => ['kabul', 'depoda'].includes(s.status)).length, 'building', 'warn')}${kpi('Teslim başarısı (7 gün)', '%' + rate, 'check', 'ok')}</div>
      <div class="grid g-21 mb"><div class="card"><div class="card-h"><h3>Günlük gönderi adedi</h3></div><div class="card-b">${chart.bars(ser.labels.map((l, i) => ({ label: l, value: ser.values[i] })))}</div></div>
      <div class="card"><div class="card-h"><h3>Hizmet dağılımı</h3></div><div class="card-b">${chart.donut(Object.entries(NS.groupBy(all, (s) => s.service)).map(([k, v]) => ({ label: K.SERVICE[k][0], value: v.length })), { size: 130 })}</div></div></div>
      <div class="grid g2"><div class="card"><div class="card-h"><h3>${icon('alert')} Teslim edilemeyenler</h3></div>${table({ rows: all.filter((s) => s.status === 'edilemedi').slice(-8).reverse(), empty: 'Yok', columns: [{ label: 'Takip', render: (s) => `<b class="mono">${esc(s.no)}</b>` }, { label: 'Alıcı', render: (s) => esc(s.receiver.name) }, { label: 'Neden', render: (s) => badge(s.failReason || '-', 'err') }], actions: [{ icon: 'eye', act: 'v' }] })}</div>
      <div class="card"><div class="card-h"><h3>Kurye performansı (bugün)</h3></div>${table({ rows: db.all('couriers').map((c) => ({ id: c.id, c, on: all.filter((s) => s.courier === c.id && s.status === 'dagitimda').length, ok: all.filter((s) => s.courier === c.id && s.status === 'teslim' && iso(s.history[s.history.length - 1].at) === t).length })), columns: [{ label: 'Kurye', render: (r) => `<b>${esc(r.c.name)}</b>` }, { label: 'Dağıtımda', cls: 'right', key: 'on' }, { label: 'Teslim', cls: 'right', key: 'ok' }] })}</div></div>`;
    on(el, 'click', '[data-act=v]', (e, b) => shipModal(app, db.get('ships', b.dataset.id)));
  }
  function carisPage(el, p, app) {
    const mo = today().slice(0, 7); const d0 = new Date(); const prev = iso(new Date(d0.getFullYear(), d0.getMonth() - 1, 1)).slice(0, 7);
    const moName = (m) => `${NS.MONTHS[Number(m.slice(5)) - 1]} ${m.slice(0, 4)}`;
    // Cari gönderiler bir kez gruplanır (müşteri × gönderi taraması binlerce kayıtta yavaştı); aylık fatura ve ekstre yalnızca cari ödemeli gönderileri kapsar
    const byCari = NS.groupBy(db.all('ships', (s) => s.cari), (s) => s.cari);
    const monthly = (c, m) => (byCari[c.id] || []).filter((s) => s.at.startsWith(m) && payerOf(s) === 'cari');
    const pickMonth = async (title) => { const v = await formModal({ title, fields: [{ name: 'm', label: 'Dönem', type: 'select', options: [{ value: mo, label: moName(mo) }, { value: prev, label: moName(prev) }] }], values: { m: prev } }); return v && v.m; };
    NS.crud(el, app, {
      col: 'caris', title: 'Kurumsal Müşteriler', sub: 'İndirimli tarife, aylık toplu fatura ve ödeme takibi', single: 'Müşteri', addLabel: 'Yeni kurumsal müşteri', emptyIcon: 'building', canDelete: (c) => ((byCari[c.id] || []).length ? 'Bu müşterinin gönderisi var, silinemez' : true),
      fields: [{ name: 'name', label: 'Firma', required: true }, { name: 'contact', label: 'Yetkili' }, { name: 'phone', label: 'Telefon' }, { name: 'email', label: 'E-posta (fatura)', type: 'email' }, { name: 'district', label: 'Alım ilçesi', type: 'select', options: K.DISTRICTS }, { name: 'discount', label: 'İndirim %', type: 'number' }, { name: 'taxNo', label: 'VKN / TCKN' }, { name: 'taxOffice', label: 'Vergi dairesi' }, { name: 'address', label: 'Fatura adresi', full: true }, { name: 'city', label: 'İl' }],
      columns: [{ key: 'name', label: 'Firma', render: (c) => `<b>${esc(c.name)}</b><div class="small faint">${esc(c.contact || '')} · ${esc(c.phone || '')}</div>` }, { key: 'discount', label: 'İndirim', render: (c) => '%' + (c.discount || 0) + (c.taxNo ? '' : `<div>${badge('VKN eksik', 'warn')}</div>`) }, { label: 'Fatura', render: (c) => { const f = (c.invoices || {})[prev] || (c.invoices || {})[mo]; return f ? `${badge(`${f.no}${f.test ? ' · TEST' : ''}`, f.test ? 'warn' : 'ok')}${f.paid ? ` ${badge('Ödendi', 'ok')}` : ''}` : '<span class="faint">Kesilmedi</span>'; } }, { label: 'Açık fatura', cls: 'right', render: (c) => { const t = sum(Object.values(c.invoices || {}).filter((f) => !f.test && !f.paid), (f) => f.total || 0); return t ? `<b style="color:var(--warn)">${money(t)}</b>` : '-'; } }, { label: 'Bu ay gönderi', cls: 'right', render: (c) => monthly(c, mo).length }, { label: 'Bu ay tutar', cls: 'right', render: (c) => `<b>${money(sum(monthly(c, mo), (s) => s.price))}</b>` }],
      extraActions: [{ icon: 'print', act: 'inv', title: 'Aylık döküm' }, { icon: 'file', act: 'efat', title: 'Aylık fatura kes' }, { icon: 'check', act: 'paid', title: 'Fatura ödendi' }],
      onAction: async (a, c) => {
        if (a === 'paid') { const open = Object.entries(c.invoices || {}).filter(([, f]) => !f.test && !f.paid); if (!open.length) return toast('Ödeme bekleyen gerçek fatura yok', 'err'); const v = await formModal({ title: `${c.name} — fatura ödemesi`, fields: [{ name: 'm', label: 'Fatura', type: 'select', options: open.map(([m, f]) => ({ value: m, label: `${moName(m)} · ${f.no} · ${money(f.total || 0)}` })) }, { name: 'ref', label: 'Dekont / açıklama' }] }); if (!v) return; c.invoices[v.m] = { ...c.invoices[v.m], paid: true, paidAt: new Date().toISOString(), ref: v.ref || '', by: me() }; db.log('Kurumsal fatura ödendi', `${c.name} · ${v.m}`); db.save(); toast('Ödeme kaydedildi', 'ok'); return app.refresh(); }
        // Aylık toplu fatura: ayın cari gönderileri tek kalemde; aynı ay ikinci kez kesilmez (TEST olan yeniden kesilebilir)
        if (a === 'efat') {
          if (!NS.ebelge) return toast('e-Belge modülü yüklü değil', 'err');
          const mo = await pickMonth(`${c.name} — fatura dönemi`); if (!mo) return;
          const prev = (c.invoices || {})[mo]; if (prev && !prev.test) return toast(`${mo} faturası zaten kesildi: ${prev.no}`, 'err');
          const list = monthly(c, mo); if (!list.length) return toast('Bu dönemde faturalanacak cari gönderi yok', 'err');
          if (!c.taxNo) return toast('Önce müşterinin VKN / TCKN bilgisini girin', 'err');
          if (!(await confirm(`${c.name}: ${list.length} gönderi, ${money(sum(list, (s) => s.price))} (KDV dahil) faturalansın mı?`))) return;
          const r = await NS.ebelge.create({ docType: 'auto', no: `${c.id}-${mo}`, buyer: c.name, buyerVkn: c.taxNo, buyerTaxOffice: c.taxOffice || '', buyerEmail: c.email || '', address: c.address || '', district: c.district || '', city: c.city || '', lines: [{ name: `Kargo taşıma hizmeti ${NS.MONTHS[Number(mo.slice(5)) - 1]} ${mo.slice(0, 4)} (${list.length} gönderi)`, qty: 1, vat: vat(), total: Math.round(sum(list, (s) => s.price) * 100) / 100 }], note: `${list.length} gönderi · döküm ektedir` });
          if (r && r.ok) { c.invoices = { ...(c.invoices || {}), [mo]: { no: r.no, type: r.type, test: !!r.simulated, n: list.length, total: r2(sum(list, (s) => s.price)), at: new Date().toISOString() } }; db.save(); app.refresh(); }
          return;
        } const m = await pickMonth(`${c.name} — döküm dönemi`); if (!m) return; const list = monthly(c, m); if (!list.length) return toast('Bu dönemde cari gönderi yok', 'err'); NS.docs.print('dokum', statementDoc(c, m, list)); },
    });
  }
  function couriersPage(el, p, app) {
    const mo = today().slice(0, 7); const by = NS.groupBy(db.all('ships', (s) => s.courier), (s) => s.courier); const d30 = addDays(new Date(), -30).toISOString();
    NS.crud(el, app, { col: 'couriers', title: 'Kuryeler', single: 'Kurye', addLabel: 'Yeni kurye', emptyIcon: 'user', canDelete: (c) => ((by[c.id] || []).length ? 'Bu kuryenin gönderi kaydı var, silinemez' : true), extraActions: [{ icon: 'print', act: 'prim', title: 'Bu ayın hakediş dökümü' }], onAction: (a, c) => { if (a === 'prim') NS.docs.print('prim', primDoc(c, mo, primOf(c, mo))); }, fields: [{ name: 'name', label: 'Ad soyad', required: true }, { name: 'phone', label: 'Telefon' }, { name: 'vehicle', label: 'Araç', type: 'select', options: ['Motor', 'Panelvan', 'Kamyonet', 'Bisiklet'] }, { name: 'plate', label: 'Plaka' }, { name: 'prim', label: 'Teslim başına prim (₺)', type: 'number', step: '0.01', hint: 'Boşsa ayarlardaki tutar' }, { name: 'zoneStr', label: 'Bölgeler (virgülle)', full: true, hint: K.DISTRICTS.join(', ') }], toForm: (r) => ({ ...r, zoneStr: (r.zone || []).join(', ') }), beforeSave: (v) => { v.zone = v.zoneStr.split(',').map((x) => x.trim()).filter(Boolean); delete v.zoneStr; }, columns: [{ key: 'name', label: 'Kurye', render: (c) => `<b>${esc(c.name)}</b><div class="small faint">${esc(c.phone || '')}</div>` }, { key: 'vehicle', label: 'Araç', render: (c) => `${esc(c.vehicle)} · ${esc(c.plate || '')}` }, { label: 'Bölgeler', render: (c) => (c.zone || []).map((z) => badge(z)).join(' ') }, { label: '30 gün teslim', cls: 'right', render: (c) => (by[c.id] || []).filter((s) => s.status === 'teslim' && s.at > d30).length }, { label: 'Bu ay prim', cls: 'right', render: (c) => { const r = primOf(c, mo); return r.rate ? `<b>${money(r.total)}</b><div class="small faint">${r.n} teslim</div>` : '<span class="faint">Tanımsız</span>'; } }] });
  }
  function reportsPage(el, p, app) {
    const st = (reportsPage.st = reportsPage.st || { k: '30' }); const d = new Date(); const mo = iso(d).slice(0, 7); const lm = iso(new Date(d.getFullYear(), d.getMonth() - 1, 1)).slice(0, 7);
    const inP = st.k === 'ay' ? (s) => s.at.startsWith(mo) : st.k === 'gecen' ? (s) => s.at.startsWith(lm) : (s) => s.at > addDays(new Date(), -30).toISOString();
    const all = db.all('ships', inP);
    const fin = all.filter((s) => ['teslim', 'edilemedi', 'iade'].includes(s.status));
    const hrs = all.filter((s) => s.status === 'teslim').map((s) => (new Date(s.history[s.history.length - 1].at) - new Date(s.at)) / 3600000);
    // Şube: kabulde seçilen şube; eski kayıtlarda göndericinin ilçesi
    const byB = Object.entries(NS.groupBy(all, (s) => s.branch || s.sender.district || 'Belirsiz')).map(([name, v]) => { const ok = v.filter((s) => s.status === 'teslim').length; const end = v.filter((s) => ['teslim', 'edilemedi', 'iade'].includes(s.status)).length; return { id: name, name, n: v.length, rev: sum(v, (s) => s.price), rate: end ? Math.round((ok / end) * 100) : null, kt: sum(v, (s) => s.cod) }; }).sort((a, b) => b.rev - a.rev);
    const cm = st.k === 'gecen' ? lm : mo; const prims = db.all('couriers').map((c) => ({ id: c.id, c, r: primOf(c, cm) }));
    el.innerHTML = pageHead('Raporlar', 'Şube, kurye ve teslim performansı', `<select class="input" id="pk" style="width:auto"><option value="30" ${st.k === '30' ? 'selected' : ''}>Son 30 gün</option><option value="ay" ${st.k === 'ay' ? 'selected' : ''}>Bu ay</option><option value="gecen" ${st.k === 'gecen' ? 'selected' : ''}>Geçen ay</option></select>`) + `<div class="grid g4 mb">${kpi('Gönderi', all.length, 'box')}${kpi('Ciro', money(sum(all, (s) => s.price)), 'trend', 'ok')}${kpi('Ort. teslim süresi', (hrs.length ? sum(hrs) / hrs.length : 0).toFixed(1) + ' saat', 'clock', 'info')}${kpi('İlk denemede teslim', '%' + (fin.length ? Math.round((fin.filter((s) => s.status === 'teslim' && !s.attempts).length / fin.length) * 100) : 0), 'check', 'warn')}</div>
      <div class="grid g3"><div class="card"><div class="card-h"><h3>İlçelere göre</h3></div><div class="card-b">${chart.bars(Object.entries(NS.groupBy(all.filter((s) => s.receiver.district), (s) => s.receiver.district)).map(([l, v]) => ({ label: l.slice(0, 6), value: v.length })).sort((a, b) => b.value - a.value))}</div></div>
      <div class="card"><div class="card-h"><h3>Teslim edilememe nedenleri</h3></div><div class="card-b">${chart.donut(Object.entries(NS.groupBy(all.filter((s) => s.failReason), (s) => s.failReason)).map(([label, v]) => ({ label, value: v.length })), { size: 120 })}</div></div>
      <div class="card"><div class="card-h"><h3>Kurumsal / bireysel</h3></div><div class="card-b">${chart.donut([{ label: 'Kurumsal', value: all.filter((s) => s.cari).length }, { label: 'Bireysel', value: all.filter((s) => !s.cari).length }], { size: 120 })}</div></div></div>
      <div class="grid g2 mt"><div class="card"><div class="card-h"><h3>Şube bazında</h3></div>${table({ rows: byB, empty: 'Bu dönemde gönderi yok', columns: [{ label: 'Şube', render: (x) => `<b>${esc(x.name)}</b>` }, { label: 'Gönderi', cls: 'right', key: 'n' }, { label: 'Ciro', cls: 'right', render: (x) => money(x.rev) }, { label: 'Teslim başarısı', cls: 'right', render: (x) => (x.rate === null ? '-' : '%' + x.rate) }, { label: 'KT', cls: 'right', render: (x) => money(x.kt) }] })}</div>
      <div class="card"><div class="card-h"><h3>Kurye hakedişi (${esc(cm)})</h3></div>${table({ rows: prims, columns: [{ label: 'Kurye', render: (x) => `<b>${esc(x.c.name)}</b>` }, { label: 'Teslim', cls: 'right', render: (x) => x.r.n }, { label: 'Birim', cls: 'right', render: (x) => (x.r.rate ? money(x.r.rate) : '-') }, { label: 'Prim', cls: 'right', render: (x) => (x.r.rate ? `<b>${money(x.r.total)}</b>` : '<span class="faint">Tanımsız</span>') }] })}</div></div>
      ${branches().length ? '' : '<p class="small faint mt">Şube tanımlı değil: rapor göndericinin ilçesine göre gruplanır. Şubeleri Tarife & Ayarlar ekranından girin.</p>'}`;
    $('#pk', el).onchange = (e) => { st.k = e.target.value; app.refresh(); };
  }

  const ROLES = { admin: 'Operasyon müdürü', kabul: 'Kabul / şube', kurye: 'Kurye' };
  const app = NS.shell({
    id: 'kargo', integrations: ['sms','whatsapp','label','printer','efatura','gps','webhook','backup'], name: 'Kargo & Kurye', tagline: 'Gönderi & Dağıtım Yönetimi', icon: 'truck', accent: '#ea580c', db, home: 'ozet', auth: { roles: ROLES },
    nav: [{ sec: 'Operasyon' }, { id: 'ozet', label: 'Özet', icon: 'home', roles: ['kabul'] }, { id: 'kabul', label: 'Gönderi Kabul', icon: 'plus', roles: ['kabul'] }, { id: 'gonderiler', label: 'Gönderiler', icon: 'box', roles: ['kabul'] }, { id: 'zimmet', label: 'Zimmet & Dağıtım', icon: 'layers', roles: ['kabul'] }, { id: 'kurye', label: 'Kurye Ekranı', icon: 'truck' }, { sec: 'Finans' }, { id: 'mutabakat', label: 'KT Mutabakatı', icon: 'cash', roles: ['admin'] }, { id: 'cariler', label: 'Kurumsal Müşteriler', icon: 'building', roles: ['admin'] }, { id: 'kuryeler', label: 'Kuryeler', icon: 'user', roles: ['admin'] }, { id: 'raporlar', label: 'Raporlar', icon: 'chart', roles: ['admin'] }, { id: 'ayarlar', label: 'Tarife & Ayarlar', icon: 'settings', roles: ['admin'] }],
    routes: { ozet: dashboard, kabul: intakePage, gonderiler: shipsPage, zimmet: assignPage, kurye: courierPage, mutabakat: settlePage, cariler: carisPage, kuryeler: couriersPage, raporlar: reportsPage, ayarlar: (el, p, a) => NS.settingsPage(el, a, { roles: ROLES, fields: [{ type: 'section', label: 'Tarife' }, { name: 'tiers', label: 'Desi kademeleri (desi:fiyat,...)', full: true, hint: 'Örn. 1:90,5:120,10:160' }, { name: 'perDesi', label: 'Son kademe üstü desi başı (₺)', type: 'number' }, { name: 'codPct', label: 'Kapıda tahsilat komisyonu %', type: 'number' }, { name: 'codMin', label: 'KT en az ücret (₺)', type: 'number' }, { name: 'vat', label: 'Gönderi ücreti KDV oranı (%)', type: 'number', hint: 'Fiyatlar KDV dahildir; oranı mali müşavirinize doğrulatın' }, { type: 'section', label: 'Operasyon' }, { name: 'branches', label: 'Şubeler (virgülle)', full: true, hint: 'Kabulde seçilir, raporda ayrılır' }, { name: 'homeCity', label: 'Şehir içi sayılan il', hint: "Excel aktarımında kullanılır; boşsa İstanbul" }, { name: 'primDefault', label: 'Teslim başına kurye primi (₺)', type: 'number', step: '0.01' }, { name: 'smsOnDispatch', label: 'Dağıtıma çıkınca alıcıya SMS gönder', type: 'checkbox' }] }) },
  });
  if (myCourier() && !location.hash.includes('kurye')) app.go('kurye');
})();
